const chapterViewCache=new WeakMap();
function chapterShoeView(raw,index,full){if(!raw?.width)return null;let views=chapterViewCache.get(raw);if(!views)chapterViewCache.set(raw,views=new Map());const key=full?'full':index;if(views.has(key))return views.get(key);const columns=[0,.35,.72,1],rows=[0,.46,1],ix=index%3,iy=Math.floor(index/3),sx=full?0:columns[ix]*raw.width,sy=full?0:rows[iy]*raw.height,W=Math.floor(full?raw.width:(columns[ix+1]-columns[ix])*raw.width),H=Math.floor(full?raw.height:(rows[iy+1]-rows[iy])*raw.height),cv=Object.assign(document.createElement('canvas'),{width:W,height:H}),cc=cv.getContext('2d');cc.drawImage(raw,Math.floor(sx),Math.floor(sy),W,H,0,0,W,H);const a=cc.getImageData(0,0,W,H).data;let l=W,r=0,top=H,b=0;for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(a[(y*W+x)*4+3]>16){l=Math.min(l,x);r=Math.max(r,x);top=Math.min(top,y);b=Math.max(b,y);}if(r<l)return null;const out=Object.assign(document.createElement('canvas'),{width:r-l+1,height:b-top+1});out.getContext('2d').drawImage(cv,l,top,out.width,out.height,0,0,out.width,out.height);views.set(key,out);return out;}
